struct Law:PrivateShopPermissionRead {const CommonStore* common=nullptr;StableId permit,clearance;bool fail_history=false;mutable bool observed_written_assets=false;
 Outcome<PrivateShopPermissionSource> private_shop_opening_permission(const PrivateShopPermissionRequest& request)const override{return {true,{common->state().identity,request,permit,clearance,0,common->tick(),1000},{}};}
 Outcome<PrivateShopPermissionSource> private_shop_opening_permission_before_fact(const PrivateShopPermissionRequest& request,const StableId& id,Integer tick)const override{const auto suffix=id.substr(id.find(':')+1);observed_written_assets=common->wallet("private_shop_wallet:"+suffix)&&common->inventory("private_shop_inventory:"+suffix);if(fail_history)return {false,{},common_failure("InjectedPrivateShopHistoryFailure").error};auto out=private_shop_opening_permission(request);out.value.observed_tick=tick;return out;}
};
